    # find TIW library
    def walk(url, depth=0):
        for u in tlm.childAssetURLs(url):
            print("  "*depth, u.leafName)
            walk(u, depth+1)
    root_urls = {
        'Local': adsk.cam.LibraryLocations.LocalLibraryLocation,
    }
