    import adsk.core, adsk.cam
    design=adsk.fusion.Design.cast(adsk.core.Application.get().activeDocument.products.itemByProductType('DesignProductType'))
    body=design.rootComponent.bRepBodies.item(0)
    cam=mb.get_cam()
    holes=[10,14,18,22,26,30,34]
    for s in cam.setups:
        for op in s.operations:
            if op.name in ("Spot_Drill","Drill_Holes"):
                p=op.parameters.itemByName("holeModel")
                cv=adsk.cam.CadObjectParameterValue.cast(p.value)
                # try ObjectCollection instead of plain list
                oc=adsk.core.ObjectCollection.create()
                for i in holes: oc.add(body.faces.item(i))
                try:
                    cv.value=oc
                    print(op.name,"set via ObjectCollection, count now", len(cv.value))
                except Exception as e:
                    print(op.name,"OC failed:",e)
    return None

